-- 0355 PROD CHECK (after), read-only, ONE statement: npx --yes supabase@2.120.0 db query --linked -f scripts/ops/harness/captain-skills/after.sql
-- Wanted: 5 rows; every new_times 1; tables 1 (row level security on, no client privilege); ceilings "C:3,B:5,A:7,S:10"; fns 5;
-- client_fns 2 (cmd.captain_skill_up and world.captain_skills, to authenticated) and anon_fns 0; volatility "s/s/s/s" (captain_rank_mult,
-- captain_skill_next, world.captain_skills and public.crew_terms all STABLE); registry 2; knobs {"captain_skill_rank_pct":4,"rep_skill_base":50};
-- head 20260818000355. Generated by scripts/ops/harness/captain-skills/gen-checks.mjs from the migration's own hunks. The catalog, the four grades and two knobs are read.
begin transaction read only;
with h(fn, ord, old, new) as (values
  ('public.crew_terms(uuid,timestamp with time zone)'::text, 1, $h$             j.job_pct * public.captain_level_mult(po.id, jt.focus)
$h$, $h$             j.job_pct * public.captain_level_mult(po.id, jt.focus)
             * case when tr.rank is null then 1 else public.captain_rank_mult(tr.rank) end   -- 0355 (R2): her job's step; no row reads no knob
$h$),
  ('public.crew_terms(uuid,timestamp with time zone)'::text, 2, $h$        join public.trait_effects te on te.trait = j.job
$h$, $h$        join public.trait_effects te on te.trait = j.job
        left join public.captain_trait_rank tr on tr.player_officer_id = po.id and tr.trait = j.job   -- 0355 (R2): a merchant's captain never has a row
$h$),
  ('public.crew_terms(uuid,timestamp with time zone)'::text, 3, $h$             * te.mult * public.captain_level_mult(po.id, t.focus)
$h$, $h$             * te.mult * public.captain_level_mult(po.id, t.focus)
             * case when tr.rank is null then 1 else public.captain_rank_mult(tr.rank) end   -- 0355 (R2): the skill's step; no row reads no knob
$h$),
  ('public.crew_terms(uuid,timestamp with time zone)'::text, 4, $h$        join public.trait_effects te on te.trait = ca.trait
$h$, $h$        join public.trait_effects te on te.trait = ca.trait
        left join public.captain_trait_rank tr on tr.player_officer_id = po.id and tr.trait = ca.trait   -- 0355 (R2): a merchant's captain never has a row
$h$),
  ('public.client_rpc_entry_points()'::text, 1, $h$      ('cmd',         'promote_captain',       'text'),
$h$, $h$      ('cmd',         'promote_captain',       'text'),
      -- 0355 (R2): one captain's skills with what the next step costs, and the step bought with Reputation.
      ('world',       'captain_skills',        'text'),
      ('cmd',         'captain_skill_up',      'text, text'),
$h$)
), d as (
  select h.*, replace(pg_get_functiondef(h.fn::regprocedure), chr(13), '') as def from h
)
select fn, ord,
       (length(def) - length(replace(def, new, ''))) / length(new) as new_times,
       (select count(*) from pg_class c
         where c.oid = to_regclass('public.captain_trait_rank') and c.relrowsecurity
           and not has_table_privilege('anon', c.oid, 'select,insert,update,delete')
           and not has_table_privilege('authenticated', c.oid, 'select,insert,update,delete')) as tables,
       (select string_agg(g.code || ':' || g.max_rank, ',' order by g.ord) from public.captain_grades g) as ceilings,
       (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where (n.nspname, p.proname) in (('public', 'captain_rank_mult'), ('public', 'captain_skill_next'), ('public', 'captain_skill_up_for'), ('cmd', 'captain_skill_up'), ('world', 'captain_skills'))) as fns,
       (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where (n.nspname, p.proname) in (('public', 'captain_rank_mult'), ('public', 'captain_skill_next'), ('public', 'captain_skill_up_for'), ('cmd', 'captain_skill_up'), ('world', 'captain_skills')) and has_function_privilege('authenticated', p.oid, 'execute')) as client_fns,
       (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where (n.nspname, p.proname) in (('public', 'captain_rank_mult'), ('public', 'captain_skill_next'), ('public', 'captain_skill_up_for'), ('cmd', 'captain_skill_up'), ('world', 'captain_skills')) and has_function_privilege('anon', p.oid, 'execute')) as anon_fns,
       (select string_agg(p.provolatile::text, '/' order by x.k)
          from unnest(array['public.captain_rank_mult(integer)', 'public.captain_skill_next(uuid,text,text)', 'world.captain_skills(text)', 'public.crew_terms(uuid,timestamp with time zone)']) with ordinality x(f, k)
          join pg_proc p on p.oid = to_regprocedure(x.f)) as volatility,
       (select count(*) from public.client_rpc_entry_points() e where e.function_name in ('captain_skills', 'captain_skill_up') and e.fn is not null) as registry,
       (select jsonb_object_agg(c.key, c.value order by c.key) from public.world_config c where c.key in ('rep_skill_base', 'captain_skill_rank_pct')) as knobs,
       (select max(version) from supabase_migrations.schema_migrations) as head
  from d order by fn, ord;
commit;
